/*
 * M1.10e (decision E7): the shared handshake transcripts test-vectors/ble_handshake_v1.txt,
 * generated by an implementation independent of noise-c (Rust snow), replayed through the REAL
 * device: dsp_app + dsp_blesec (noise-c responder) inside the test_blesec world (fake storage,
 * pump and time). The device's randomness is scripted per transcript (test_rng_script: the HELLO
 * session ID, the identity key generated at claim/recovery, the ephemeral key, the invite token),
 * so every frame the device sends must equal the vector byte for byte, and every phone frame of the
 * vector must be accepted. Negative records: the device must answer HANDSHAKE_FAILED or close
 * without any reply, exactly as recorded, and store nothing.
 *
 * Host verification only; deterministic randomness exists only in host tests (test_rng.h).
 */
#define DSP_BLESEC_NO_MAIN
#include "test_blesec.c"

#include <stdlib.h>

#define VMAX_FRAMES 8
#define VMAX_HS 8
#define VMAX_NEG 12

typedef struct {
    int n;
    bool d2p;
    uint8_t b[DSP_BLE_FRAME_MAX];
    size_t len;
} vframe_t;

typedef struct {
    char id[24];
    uint8_t purpose, claim_state, hello_flags;
    uint32_t session_id;
    uint8_t device_id[6], hash8[8], setup[16];
    uint8_t phone_pub[32], device_static[32], device_pub[32], device_eph[32];
    uint8_t name[32];
    size_t name_len;
    vframe_t f[VMAX_FRAMES];
    int nf;
} vhs_t;

typedef struct {
    char id[40], base[24], expect[20];
    int frame;
    uint8_t b[DSP_BLE_FRAME_MAX];
    size_t len;
} vneg_t;

static vhs_t VH[VMAX_HS];
static int g_nvh;
static vneg_t VN[VMAX_NEG];
static int g_nvn;

/* ---- parsing ------------------------------------------------------------------------------- */

static const char *tok(const char *line, const char *key, char *out, size_t cap)
{
    char pat[48];
    snprintf(pat, sizeof pat, " %s=", key);
    const char *p = strstr(line, pat);
    if (p == NULL) {
        return NULL;
    }
    p += strlen(pat);
    size_t n = strcspn(p, " \n");
    if (n >= cap) {
        return NULL;
    }
    memcpy(out, p, n);
    out[n] = 0;
    return out;
}

static size_t unhex(const char *s, uint8_t *out, size_t cap)
{
    if (strcmp(s, "-") == 0) {
        return 0;
    }
    if (strncmp(s, "x:", 2) == 0) {
        s += 2;
    }
    size_t n = strlen(s) / 2;
    DSP_CHECK(strlen(s) % 2 == 0 && n <= cap);
    for (size_t i = 0; i < n && i < cap; i++) {
        unsigned v = 0;
        DSP_CHECK(sscanf(s + 2 * i, "%2x", &v) == 1);
        out[i] = (uint8_t)v;
    }
    return n < cap ? n : cap;
}

static vhs_t *find_hs(const char *id)
{
    for (int i = 0; i < g_nvh; i++) {
        if (strcmp(VH[i].id, id) == 0) {
            return &VH[i];
        }
    }
    return NULL;
}

static void load_vectors(void)
{
    char path[512];
    snprintf(path, sizeof path, "%s/%s", DSP_VECTORS_DIR, "ble_handshake_v1.txt");
    FILE *fp = fopen(path, "r");
    DSP_CHECK(fp != NULL);
    if (fp == NULL) {
        return;
    }
    static char line[4096];
    char v[2200];
    while (fgets(line, sizeof line, fp) != NULL) {
        if (line[0] == '#' || line[0] == '\n') {
            continue;
        }
        if (strncmp(line, "hs ", 3) == 0 && g_nvh < VMAX_HS) {
            vhs_t *h = &VH[g_nvh++];
            memset(h, 0, sizeof *h);
            snprintf(h->id, sizeof h->id, "%s", tok(line, "id", v, sizeof v));
            h->purpose = (uint8_t)atoi(tok(line, "purpose", v, sizeof v));
            h->claim_state = (uint8_t)atoi(tok(line, "claim_state", v, sizeof v));
            h->hello_flags = (uint8_t)atoi(tok(line, "hello_flags", v, sizeof v));
            h->session_id = (uint32_t)strtoul(tok(line, "session_id", v, sizeof v), NULL, 10);
            unhex(tok(line, "device_id", v, sizeof v), h->device_id, 6);
            unhex(tok(line, "device_id_hash", v, sizeof v), h->hash8, 8);
            unhex(tok(line, "setup", v, sizeof v), h->setup, 16);
            unhex(tok(line, "phone_static_pub", v, sizeof v), h->phone_pub, 32);
            unhex(tok(line, "device_static", v, sizeof v), h->device_static, 32);
            unhex(tok(line, "device_static_pub", v, sizeof v), h->device_pub, 32);
            unhex(tok(line, "device_ephemeral", v, sizeof v), h->device_eph, 32);
            h->name_len = unhex(tok(line, "name", v, sizeof v), h->name, sizeof h->name);
        } else if (strncmp(line, "frame ", 6) == 0 || strncmp(line, "enc ", 4) == 0) {
            vhs_t *h = find_hs(tok(line, "id", v, sizeof v));
            DSP_CHECK(h != NULL && h->nf < VMAX_FRAMES);
            if (h == NULL || h->nf >= VMAX_FRAMES) {
                continue;
            }
            vframe_t *f = &h->f[h->nf++];
            f->n = atoi(tok(line, "n", v, sizeof v));
            f->d2p = strcmp(tok(line, "dir", v, sizeof v), "d2p") == 0;
            f->len = unhex(tok(line, "bytes", v, sizeof v), f->b, sizeof f->b);
        } else if (strncmp(line, "neg ", 4) == 0 && g_nvn < VMAX_NEG) {
            vneg_t *n = &VN[g_nvn++];
            memset(n, 0, sizeof *n);
            snprintf(n->id, sizeof n->id, "%s", tok(line, "id", v, sizeof v));
            snprintf(n->base, sizeof n->base, "%s", tok(line, "base", v, sizeof v));
            snprintf(n->expect, sizeof n->expect, "%s", tok(line, "expect", v, sizeof v));
            n->frame = atoi(tok(line, "frame", v, sizeof v));
            n->len = unhex(tok(line, "bytes", v, sizeof v), n->b, sizeof n->b);
        }
    }
    fclose(fp);
}

/* ---- replay ------------------------------------------------------------------------------- */

static const uint8_t *g_vpost[VMAX_FRAMES + 1];
static size_t g_vpost_len[VMAX_FRAMES + 1];

static void h_vpost(int step_i)
{
    int i = sc.op[step_i].a;
    post(g_vpost[i], g_vpost_len[i]);
}

/* the three confirmation presses (as h_press3, without draining the captured frames) */
static void h_vpress(int step_i)
{
    (void)step_i;
    uint64_t base = mono_ms + 400;
    for (int k = 0; k < 3; k++) {
        dsp_button_event_t e = {DSP_BUTTON_SHORT, base + (uint64_t)k * 400, base + (uint64_t)k * 400 + 100};
        (void)dsp_app_post_button(&app, &e);
    }
}

/* > 0: replay only the phone frames up to this n (the phone disappears afterwards) */
static int g_stop_after;

static const uint8_t HELLO_REQ[10] = {1, 0, 1, 0, 1, 0, 2, 0, 1, 1};

/* Scripts the device's randomness for one transcript of the vector file. */
static void script_rng(const vhs_t *h, const uint8_t *invite_token)
{
    test_rng_script_clear();
    uint8_t sid[4] = {(uint8_t)h->session_id, (uint8_t)(h->session_id >> 8), (uint8_t)(h->session_id >> 16),
                      (uint8_t)(h->session_id >> 24)};
    DSP_CHECK(test_rng_script(sid, 4));
    if (h->purpose == DSP_SEC_CLAIM || h->purpose == DSP_SEC_RECOVERY) {
        DSP_CHECK(test_rng_script(h->device_static, 32)); /* identity generated by the device */
    }
    DSP_CHECK(test_rng_script(h->device_eph, 32));
    if (invite_token != NULL) {
        DSP_CHECK(test_rng_script(invite_token, 16));
    }
}

/* Raw copy of every frame the device sends (independent of the harness's drain on disconnect). */
#define VOUT_MAX 32
static uint8_t g_vout[VOUT_MAX][DSP_BLE_FRAME_MAX];
static size_t g_vout_len[VOUT_MAX];
static int g_vout_head, g_vout_count;

static bool vcap_send(void *ctx, uint32_t gen, const uint8_t *f, size_t n)
{
    bool ok = cap_send(ctx, gen, f, n);
    if (ok && g_vout_count < VOUT_MAX && n <= DSP_BLE_FRAME_MAX) {
        int i = (g_vout_head + g_vout_count) % VOUT_MAX;
        memcpy(g_vout[i], f, n);
        g_vout_len[i] = n;
        g_vout_count++;
    }
    return ok;
}

/* Takes the next frame the device sent. */
static bool next_out(uint8_t *out, size_t *len)
{
    if (g_vout_count == 0) {
        return false;
    }
    *len = g_vout_len[g_vout_head];
    memcpy(out, g_vout[g_vout_head], *len);
    g_vout_head = (g_vout_head + 1) % VOUT_MAX;
    g_vout_count--;
    return true;
}

static void check_hello(const vhs_t *h)
{
    uint8_t f[DSP_BLE_FRAME_MAX];
    size_t n = 0;
    DSP_CHECK(next_out(f, &n));
    dsp_ble_msg_t m;
    DSP_CHECK_EQ_INT(DSP_BLE_OK, dsp_ble_decode(f, n, DSP_BLE_MINOR, &m));
    DSP_CHECK_EQ_INT(DSP_BLE_T_HELLO, m.h.type);
    DSP_CHECK_EQ_INT(1, m.b.hello_rsp.proto);
    DSP_CHECK_EQ_INT(h->claim_state, m.b.hello_rsp.claim_state);
    DSP_CHECK_EQ_INT(h->hello_flags, m.b.hello_rsp.flags);
    DSP_CHECK(m.b.hello_rsp.session_id == h->session_id);
    DSP_CHECK(memcmp(m.b.hello_rsp.device_id_hash, h->hash8, 8) == 0);
}

/* Replays transcript h (optionally with a negative frame replacing frame neg_n and stopping there).
 * Returns the number of device frames matched. */
static int replay(const vhs_t *h, const uint8_t *invite_token, const vneg_t *neg)
{
    memcpy(g_dev_setup, h->setup, 16);
    script_rng(h, invite_token);
    CFG.recovery_hold_ms = h->purpose == DSP_SEC_RECOVERY ? DSP_OWNER_ARM_HOLD_MS : 0;
    window_begin();
    g_vout_head = g_vout_count = 0;
    dsp_utc_t t = g_true;
    int np = 0;
    g_vpost[np] = HELLO_REQ;
    g_vpost_len[np] = sizeof HELLO_REQ;
    step(t++, hk(h_vpost, np++, 0));
    for (int i = 0; i < h->nf; i++) {
        const vframe_t *f = &h->f[i];
        if (f->d2p) {
            continue;
        }
        if (g_stop_after > 0 && f->n > g_stop_after) {
            break;
        }
        if (neg != NULL && f->n == neg->frame) {
            g_vpost[np] = neg->b;
            g_vpost_len[np] = neg->len;
            step(t++, hk(h_vpost, np++, 0));
            break;
        }
        g_vpost[np] = f->b;
        g_vpost_len[np] = f->len;
        step(t++, hk(h_vpost, np++, 0));
        if (h->purpose == DSP_SEC_RECOVERY && f->n == 3) {
            step(t++, hk(h_vpress, 0, 0)); /* confirmation on the device */
            t += 3;
        }
    }
    step(t + 2, mk(OP_END_TIMEOUT));
    DSP_CHECK(session());
    CFG.recovery_hold_ms = 0;
    check_hello(h);
    if (g_stop_after > 0) {
        return 0; /* the phone never processed the device's later frames */
    }
    int matched = 0;
    uint8_t out[DSP_BLE_FRAME_MAX];
    size_t n = 0;
    for (int i = 0; i < h->nf; i++) {
        const vframe_t *f = &h->f[i];
        if (!f->d2p || (neg != NULL && f->n > neg->frame)) {
            continue;
        }
        bool got = next_out(out, &n);
        DSP_CHECK(got);
        if (!got) {
            fprintf(stderr, "%s: device frame %d missing (blesec state %u, fail_line %u)\n", h->id, f->n,
                    SECS.state, SECS.fail_line);
            break;
        }
        bool same = n == f->len && memcmp(out, f->b, n) == 0;
        DSP_CHECK(same);
        if (!same) {
            fprintf(stderr, "%s: device frame %d differs (len %zu vs %zu)\n", h->id, f->n, n, f->len);
            break;
        }
        matched++;
    }
    if (neg == NULL) {
        DSP_CHECK_EQ_INT(0, g_vout_count); /* nothing else was sent */
        DSP_CHECK_EQ_INT(0, (int)test_rng_script_pending()); /* every scripted draw was used */
    }
    return matched;
}

/* The device's reaction to a negative frame: a plain HANDSHAKE_FAILED error for that txn, or no
 * reply at all; then the connection is closed. */
static void check_negative_tail(const vneg_t *neg)
{
    uint8_t out[DSP_BLE_FRAME_MAX];
    size_t n = 0;
    uint16_t txn = (uint16_t)(neg->b[4] | (neg->b[5] << 8));
    if (strcmp(neg->expect, "device_rejects") == 0) {
        DSP_CHECK(next_out(out, &n));
        dsp_ble_msg_t m;
        DSP_CHECK_EQ_INT(DSP_BLE_OK, dsp_ble_decode(out, n, DSP_BLE_MINOR, &m));
        DSP_CHECK((m.h.flags & DSP_BLE_F_ERROR) && !(m.h.flags & DSP_BLE_F_ENCRYPTED));
        DSP_CHECK_EQ_INT(DSP_BLE_T_HS, m.h.type);
        DSP_CHECK_EQ_INT(txn, m.h.txn);
        DSP_CHECK_EQ_INT(DSP_BLE_E_HANDSHAKE_FAILED, m.b.error.code);
    } else {
        DSP_CHECK(strcmp(neg->expect, "device_drops") == 0);
    }
    DSP_CHECK_EQ_INT(0, g_vout_count); /* nothing else, in particular no plaintext after auth */
    DSP_CHECK(g_disconnects_seen >= 1);
}

static void device_world(const vhs_t *h)
{
    memcpy(DEV_ID, h->device_id, 6);
    fresh_unclaimed();
    BLE2.send_frame = vcap_send;
}

/* invite token of session_a = the first 16 plaintext bytes of its INVITE_CREATE response */
static const uint8_t TOKEN[16] = {0xba, 0xcd, 0x0f, 0xa8, 0x87, 0x9e, 0xa4, 0xdd,
                                  0x10, 0x4c, 0x41, 0x2f, 0x93, 0xe1, 0xa7, 0xcb};

static void test_positive_chain(void)
{
    static const char *order[] = {"claim_a", "session_a", "add_b", "session_b", "recovery_c", "session_c"};
    vhs_t *first = find_hs("claim_a");
    DSP_CHECK(first != NULL && g_nvh == 6);
    if (first == NULL) {
        return;
    }
    device_world(first);
    int frames = 0;
    for (size_t k = 0; k < sizeof order / sizeof order[0]; k++) {
        vhs_t *h = find_hs(order[k]);
        DSP_CHECK(h != NULL);
        if (h == NULL) {
            return;
        }
        frames += replay(h, strcmp(h->id, "session_a") == 0 ? TOKEN : NULL, NULL);
        dsp_auth_t a = durable_auth();
        DSP_CHECK(memcmp(a.id_pub, h->device_pub, 32) == 0); /* the identity in use */
        if (h->purpose != DSP_SEC_SESSION) {
            int slot = h->purpose == DSP_SEC_ADD ? 1 : 0;
            DSP_CHECK(a.slot[slot].used && memcmp(a.slot[slot].pub, h->phone_pub, 32) == 0);
            DSP_CHECK(a.slot[slot].name_len == h->name_len &&
                      memcmp(a.slot[slot].name, h->name, h->name_len) == 0);
        }
        if (h->purpose == DSP_SEC_RECOVERY) {
            DSP_CHECK(!a.slot[1].used); /* recovery removed every other phone */
        }
        dsp_auth_wipe(&a);
        check_zeroized();
    }
    printf("handshake vectors: %d transcripts, %d device frames byte-identical\n", g_nvh, frames);
    DSP_CHECK(frames == 17); /* 3 + 3 + 3 + 2 + 4 + 2 */
    invariants();
}

/* Runs the transcripts the negative's base needs, then the base up to the negative frame. */
static void test_negatives(void)
{
    int run = 0;
    for (int i = 0; i < g_nvn; i++) {
        const vneg_t *neg = &VN[i];
        if (strncmp(neg->expect, "device_", 7) != 0) {
            continue; /* phone-side cases: the Android client consumes them */
        }
        vhs_t *claim = find_hs("claim_a");
        vhs_t *base = find_hs(neg->base);
        DSP_CHECK(claim != NULL && base != NULL);
        if (claim == NULL || base == NULL) {
            return;
        }
        device_world(claim);
        if (strcmp(neg->base, "claim_a") != 0) {
            replay(claim, NULL, NULL);
        }
        if (strcmp(neg->base, "add_b") == 0) {
            replay(find_hs("session_a"), TOKEN, NULL); /* the invitation */
        }
        dsp_auth_t before = durable_auth();
        replay(base, NULL, neg);
        check_negative_tail(neg);
        dsp_auth_t after = durable_auth();
        bool unchanged = memcmp(before.id_pub, after.id_pub, 32) == 0 &&
                         memcmp(before.slot, after.slot, sizeof before.slot) == 0 &&
                         before.claim_state == after.claim_state;
        /* the encrypted-frame negatives come after a successful enrollment */
        if (neg->frame <= 3) {
            DSP_CHECK(unchanged);
            if (!unchanged) {
                fprintf(stderr, "negative %s changed the credential record\n", neg->id);
            }
        }
        dsp_auth_wipe(&before);
        dsp_auth_wipe(&after);
        check_zeroized();
        run++;
    }
    printf("handshake vectors: %d device-side negative cases\n", run);
    DSP_CHECK(run >= 7);
    invariants();
}

/* M1.10e (docs/ANDROID_BLE_DESIGN.md 11.7): the final ENROLL_RESULT is lost after the device
 * committed the enrollment (CLAIM, ADD). The device's state must let the phone confirm its staged
 * enrollment with an IK SESSION using the staged key and the device key from message 2 — the next
 * transcript must succeed byte for byte. If message 3 never reached the device, nothing is stored
 * (CLAIM: still unclaimed), so the phone's IK attempt cannot succeed and it must not assume
 * enrollment. */
static void test_lost_enroll_result(void)
{
    vhs_t *claim = find_hs("claim_a"), *sa = find_hs("session_a"), *add = find_hs("add_b"), *sb = find_hs("session_b");
    DSP_CHECK(claim != NULL && sa != NULL && add != NULL && sb != NULL);
    if (claim == NULL || sa == NULL || add == NULL || sb == NULL) {
        return;
    }
    /* message 3 never arrived: nothing stored */
    device_world(claim);
    g_stop_after = 1;
    replay(claim, NULL, NULL);
    g_stop_after = 0;
    dsp_auth_t a = durable_auth();
    DSP_CHECK_EQ_INT(DSP_AUTH_UNCLAIMED, a.claim_state);
    DSP_CHECK(!a.slot[0].used);
    dsp_auth_wipe(&a);
    check_zeroized();

    /* CLAIM: message 3 delivered, ENROLL_RESULT lost (the phone disconnects without reading it) */
    device_world(claim);
    g_stop_after = 3;
    replay(claim, NULL, NULL);
    g_stop_after = 0;
    a = durable_auth();
    DSP_CHECK_EQ_INT(DSP_AUTH_CLAIMED, a.claim_state);
    DSP_CHECK(a.slot[0].used && memcmp(a.slot[0].pub, claim->phone_pub, 32) == 0);
    DSP_CHECK(memcmp(a.id_pub, claim->device_pub, 32) == 0); /* the key the phone saw in message 2 */
    dsp_auth_wipe(&a);
    /* the staged key confirms with IK: the SESSION transcript is accepted byte for byte */
    DSP_CHECK_EQ_INT(3, replay(sa, TOKEN, NULL));

    /* ADD: ENROLL_RESULT lost, then B's IK SESSION succeeds */
    g_stop_after = 3;
    replay(add, NULL, NULL);
    g_stop_after = 0;
    a = durable_auth();
    DSP_CHECK(a.slot[1].used && memcmp(a.slot[1].pub, add->phone_pub, 32) == 0);
    dsp_auth_wipe(&a);
    DSP_CHECK_EQ_INT(2, replay(sb, NULL, NULL));
    check_zeroized();
    invariants();
}

int main(void)
{
    if (!test_rng_install(0xD15EA5E5u)) {
        return 1;
    }
    load_vectors();
    DSP_RUN(test_positive_chain);
    DSP_RUN(test_negatives);
    DSP_RUN(test_lost_enroll_result);
    test_rng_script_clear();
    return dsp_test_finish();
}
